    "contents": "Contents",
    "contentLang": "en",
    "s": {
      "commitment": {
        "title": "1. Our commitment",
        "b0": "EATS SYSTEMS TECH believes in equal access to information and services. We work to make the wifigate.io website accessible to people with disabilities, including people who use screen readers, keyboard navigation, screen magnification or voice control."
      },
      "standard": {
        "title": "2. Standard",
        "b0": "The website has been adapted to the Israeli Standard IS 5568 at level AA, which is based on the Web Content Accessibility Guidelines (WCAG) 2.0 of the W3C, in accordance with the Equal Rights for Persons with Disabilities (Service Accessibility Adjustments) Regulations, 5773-2013. We also follow the additional success criteria of WCAG 2.1 at level AA where we can.",
        "b1": "The website was tested with automated accessibility tools and by manual checks of keyboard navigation, focus, structure, text alternatives and colour contrast, on current versions of Chrome, Edge, Safari and Firefox, on desktop and mobile."
      },
      "features": {
        "title": "3. Accessibility features",
        "b0": {
          "i0": "Every page can be operated with a keyboard alone, with a visible focus indicator and a \"Skip to main content\" link at the top of the page.",
          "i1": "Pages use a clear structure of headings, landmarks and lists, so screen readers can navigate them.",
          "i2": "Images that carry information have text alternatives; decorative images and the background video are hidden from screen readers.",
          "i3": "Text and controls meet the required colour contrast, and the layout adapts to small screens and to zoom up to 200% without loss of content.",
          "i4": "Each page declares its language and reading direction, including right-to-left pages in Hebrew and Arabic.",
          "i5": "Links, buttons and form fields have accessible names.",
          "i6": "Animations respect the operating system's \"reduce motion\" setting, and the background video can be paused."
        },
        "b1": "The accessibility menu, opened with the accessibility button at the bottom of every page, lets you enlarge the text, switch to high contrast, underline links, use a more readable font and reduce motion. Your choices are remembered on your device. Press and hold the button to move it to another place on the screen, or to hide it for the current visit; it returns on your next visit."
      },
      "limitations": {
        "title": "4. Known limitations",
        "b0": "We are continuing to improve the website. The following parts may not yet be fully accessible:",
        "b1": {
          "i0": "Content provided by third parties, such as the Google and Apple sign-in windows of the web portal, WhatsApp and social networks, is under their control.",
          "i1": "On pages in languages other than English and Hebrew, the legal documents are shown in English.",
          "i2": "Some product images and older documents may lack a detailed text description."
        },
        "b2": "If you find a part of the website that is not accessible, please tell us so we can fix it."
      },
      "premises": {
        "title": "5. Physical accessibility",
        "b0": "We do not operate a physical service location that is open to the public. Service is provided online, by email and by WhatsApp."
      },
      "contact": {
        "title": "6. Accessibility contact",
        "b0": "If you need help, encounter an accessibility barrier or would like information in an accessible format, contact our accessibility coordinator. Please describe the problem, the page concerned and, if possible, the browser and assistive technology you use. We will reply as soon as possible and in any case within 14 days.",
        "b1": "Email: support@wifigate.io",
        "b2": "Message us on WhatsApp",
        "b3": "This statement is published in English and Hebrew and may be shown in English on pages in other languages. If versions differ, the English version prevails."
      }
    },
